import{_ as a,o as n,c as l,aw as t}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Установка и настройка","description":"","frontmatter":{},"headers":[],"relativePath":"common/typescript/main/install.md","filePath":"wiki/dev-commit/common/typescript/main/install.md"}'),o={name:"common/typescript/main/install.md"};function e(p,s,c,i,r,y){return n(),l("div",null,[...s[0]||(s[0]=[t(`<h1 id="установка-и-настроика" tabindex="-1">Установка и настройка <a class="header-anchor" href="#установка-и-настроика" aria-label="Permalink to &quot;Установка и настройка&quot;">​</a></h1><h2 id="минимальная-установка" tabindex="-1">Минимальная установка <a class="header-anchor" href="#минимальная-установка" aria-label="Permalink to &quot;Минимальная установка&quot;">​</a></h2><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">npm</span><span style="color:#50A14F;"> i</span><span style="color:#986801;"> -g</span><span style="color:#50A14F;"> typescript</span></span>
<span class="line"></span>
<span class="line"><span style="color:#4078F2;">tsc</span><span style="color:#50A14F;"> file.ts</span></span>
<span class="line"><span style="color:#4078F2;">node</span><span style="color:#50A14F;"> file.js</span></span></code></pre></div><h2 id="_1-установка-typescript" tabindex="-1">1. Установка TypeScript <a class="header-anchor" href="#_1-установка-typescript" aria-label="Permalink to &quot;1. Установка TypeScript&quot;">​</a></h2><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">npm</span><span style="color:#50A14F;"> i</span><span style="color:#986801;"> --save-dev</span><span style="color:#50A14F;"> typescript</span></span></code></pre></div><h3 id="добавление-tsc-в-секцию-scripts-фаила-package-json" tabindex="-1">Добавление tsc в секцию &quot;scripts&quot; файла package.json <a class="header-anchor" href="#добавление-tsc-в-секцию-scripts-фаила-package-json" aria-label="Permalink to &quot;Добавление tsc в секцию &quot;scripts&quot; файла package.json&quot;">​</a></h3><div class="language-json"><button title="Скопировать код" class="copy"></button><span class="lang">json</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">{</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">  // ...</span></span>
<span class="line"><span style="color:#E45649;">  &quot;scripts&quot;</span><span style="color:#383A42;">: {</span></span>
<span class="line"><span style="color:#E45649;">    &quot;build&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;tsc&quot;</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // ...</span></span>
<span class="line"><span style="color:#383A42;">  }</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">  // ...</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><h2 id="_2-настроика-компилятора-typescript" tabindex="-1">2. Настройка компилятора TypeScript <a class="header-anchor" href="#_2-настроика-компилятора-typescript" aria-label="Permalink to &quot;2. Настройка компилятора TypeScript&quot;">​</a></h2><h3 id="создание-конфигурационного-фаила-tsconfig-json" tabindex="-1">Создание конфигурационного файла tsconfig.json <a class="header-anchor" href="#создание-конфигурационного-фаила-tsconfig-json" aria-label="Permalink to &quot;Создание конфигурационного файла tsconfig.json&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" target="_blank" rel="noreferrer">https://www.typescriptlang.org/docs/handbook/tsconfig-json.html</a></li><li><a href="https://github.com/Microsoft/TypeScript-React-Starter/blob/master/tsconfig.json" target="_blank" rel="noreferrer">https://github.com/Microsoft/TypeScript-React-Starter/blob/master/tsconfig.json</a> - Готовый tsconfig.json для React</li></ul></div><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">npx</span><span style="color:#50A14F;"> tsc</span><span style="color:#986801;"> --init</span></span></code></pre></div><ul><li>Компилятор берёт исходный TypeScript-код и компилирует его в JavaScript. И нам нужно, чтобы не возникло путаницы между исходными файлами и сгенерированным кодом.</li><li>Эту проблему можно решить в два шага:</li><li>Во-первых, изменим структуру проекта. Все файлы с исходниками переместим в директорию src.</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">├──</span><span style="color:#50A14F;"> package.json</span></span>
<span class="line"><span style="color:#4078F2;">├──</span><span style="color:#50A14F;"> 📂</span><span style="color:#50A14F;"> src</span></span>
<span class="line"><span style="color:#4078F2;">│</span><span style="color:#50A14F;">   └──</span><span style="color:#50A14F;"> index.ts</span></span>
<span class="line"><span style="color:#4078F2;">└──</span><span style="color:#50A14F;"> tsconfig.json</span></span></code></pre></div><ul><li>Затем укажем компилятору, откуда ему брать исходные файлы и куда сохранять скомпилированный код.</li></ul><div class="language-json"><button title="Скопировать код" class="copy"></button><span class="lang">json</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// tsconfig.json</span></span>
<span class="line"><span style="color:#383A42;">{</span></span>
<span class="line"><span style="color:#E45649;">  &quot;compilerOptions&quot;</span><span style="color:#383A42;">: {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // ...</span></span>
<span class="line"><span style="color:#E45649;">    &quot;rootDir&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;src&quot;</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;outDir&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;build&quot;</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // ...</span></span>
<span class="line"><span style="color:#383A42;">  }</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><h2 id="_3-запуск-typescript" tabindex="-1">3. Запуск TypeScript <a class="header-anchor" href="#_3-запуск-typescript" aria-label="Permalink to &quot;3. Запуск TypeScript&quot;">​</a></h2><ul><li>Если эта команда не вывела ничего в терминале, то процесс компиляции прошёл успешно</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">npm</span><span style="color:#50A14F;"> run</span><span style="color:#50A14F;"> build</span></span></code></pre></div><h2 id="расширения-фаилов" tabindex="-1">Расширения файлов <a class="header-anchor" href="#расширения-фаилов" aria-label="Permalink to &quot;Расширения файлов&quot;">​</a></h2><ul><li><code>.tsx</code> - для файлов, содержащих разметку JSX</li><li><code>.ts</code> - для всего остального</li></ul><h2 id="определения-типов" tabindex="-1">Определения типов <a class="header-anchor" href="#определения-типов" aria-label="Permalink to &quot;Определения типов&quot;">​</a></h2><ul><li>Для анализа ошибок и выдачи всплывающих подсказок компилятор TypeScript использует файлы объявлений. Они содержат в себе всю информацию о типах, которые используются в конкретной библиотеке. В свою очередь это позволяет нам использовать JavaScript-библиотеки в проекте совместно с TypeScript.</li><li>Существует два основных способа получения файлов объявлений:</li><li><strong>Bundled</strong> - Библиотека устанавливается вместе с собственным файлом объявлений. Чтобы проверить, есть ли у библиотеки файл объявлений, поищите index.d.ts в её исходных файлах. В некоторых библиотеках наличие и расположение этого файла указываются в package.json в секциях typings или types.</li><li><strong><a href="https://github.com/DefinitelyTyped/DefinitelyTyped" target="_blank" rel="noreferrer">DefinitelyTyped</a></strong> - репозиторий файлов объявлений. Например, React устанавливается без собственного файла объявлений - вместо этого мы устанавливаем его отдельно:</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">npm</span><span style="color:#50A14F;"> i</span><span style="color:#986801;"> --save-dev</span><span style="color:#50A14F;"> @types/react</span></span></code></pre></div><ul><li><strong>Локальные объявления</strong> - Иногда пакет, который вы хотите использовать, не имеет ни собственного файла объявлений, ни соответствующего файла в репозитории DefinitelyTyped. В этом случае мы можем объявить собственный локальный файл объявлений. Для этого надо создать файл declarations.d.ts в корне директории, где лежат исходники вашего проекта. Файл объявлений может выглядеть примерно так:</li></ul><div class="language-ts"><button title="Скопировать код" class="copy"></button><span class="lang">ts</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">declare</span><span style="color:#A626A4;"> module</span><span style="color:#50A14F;"> &quot;querystring&quot;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A626A4;">  export</span><span style="color:#A626A4;"> function</span><span style="color:#4078F2;"> stringify</span><span style="color:#383A42;">(val</span><span style="color:#0184BC;">:</span><span style="color:#0184BC;"> object</span><span style="color:#383A42;">)</span><span style="color:#0184BC;">:</span><span style="color:#0184BC;"> string</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#A626A4;">  export</span><span style="color:#A626A4;"> function</span><span style="color:#4078F2;"> parse</span><span style="color:#383A42;">(val</span><span style="color:#0184BC;">:</span><span style="color:#0184BC;"> string</span><span style="color:#383A42;">)</span><span style="color:#0184BC;">:</span><span style="color:#0184BC;"> object</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div>`,25)])])}const h=a(o,[["render",e]]);export{u as __pageData,h as default};
